                    raise ValueError(
                        "conv_transpose1d backward intermediate "
                        "must be finite"
                    )
                contrib_k = g * a[i]
                if not math.isfinite(contrib_k):
                    raise ValueError(
                        "conv_transpose1d backward intermediate "
                        "must be finite"
